schemas.DeviceConfiguration.description='What a device was offered at its current (or an earlier) desired generation, read from the immutable content-addressed store, with the agent\'s report beside it. With nothing offered at the current generation (a device never assigned, or its assignment removed) version, sha256, size, format and content are null and previous names the last offer. Revoked devices stay readable as history.';
schemas.ConfigurationDiffLine=object({kind:{enum:['context','removed','added']},old_line:nullable({type:'integer',minimum:1}),new_line:nullable({type:'integer',minimum:1}),text:str},undefined,false);
schemas.ConfigurationDiffHunk=object({old_start:integer,old_lines:integer,new_start:integer,new_lines:integer,section:{...nullable(bounded(200)),description:'The components enclosing the first changed line, as dotted keys (sinks.out.buffer); null at the top level or when the text is not the rendered JSON.'},lines:{type:'array',maxItems:1997,items:ref('ConfigurationDiffLine')}},undefined,false);
schemas.DeviceConfigurationDiff=object({device_id:id,from:{...nullable(offeredArtifact),description:'The older side; null when nothing was offered to this device before the newer side.'},to:offeredArtifact,identical:{...bool,description:'The two sides are the same bytes.'},counts:{...object({added:integer,removed:integer,changed:integer},undefined,false),description:'Lines of the whole change, not only the part shown. A line a replaced line stands in for counts once, as changed.'},hunks:{type:'array',maxItems:1000,items:ref('ConfigurationDiffHunk')},unified:{type:'string',description:'The same hunks as a unified diff, at most 2,000 lines including its headers; when truncated, its last line is a marker.'},truncated:{...bool,description:'The diff is longer than 2,000 lines; hunks and unified stop at the same line.'},total_lines:{...integer,description:'Lines the complete unified diff would have.'},approximate:{...bool,description:'The change was too large to match line by line, so the region between the unchanged start and end is shown as replaced although some of its lines are the same on both sides.'}},undefined,false);
