route('/api/v1/devices/{id}/configuration','get','What this device was offered: the artifact at its current or an earlier generation exactly as stored (device secrets stay vectory-secret: references), the values its variables took, the generations it was offered, and whether the file its agent reports is that artifact. Any authenticated role, like reading a pipeline version. A read: nothing is written or audited. 404 for an unknown device, or for a generation it never had; 429 beyond 240 reads a minute per account',ref('DeviceConfiguration'));
paths['/api/v1/devices/{id}/configuration'].get.parameters.push({name:'generation',in:'query',schema:generationNumber,description:'An earlier generation this device was offered. Default: the current desired generation.'});
route('/api/v1/devices/{id}/configuration/diff','get','A bounded unified diff and structured hunks between two generations this device was offered (default: the previous one to the current one). Any authenticated role. 404 for an unknown device, a generation it never had, or no current offer; 429 beyond 60 a minute per account',ref('DeviceConfigurationDiff'));
