schemas.ValidationTest=object({name:{type:'string',minLength:1,maxLength:200,description:'At most 200 bytes, no control characters.'},passed:bool,not_run:{...nullable({type:'boolean'}),description:'Vector did not run this test, for example because another test could not be read or built. It never counts as passed. Null is treated as absent.'},message:{...nullable({type:'string',maxLength:512}),description:'At most 512 bytes, no control characters; redacted on the device like a diagnostic. Null is treated as absent.'}},['name','passed'],false);
schemas.ValidationTest.description='One of the pipeline\'s own tests as `vector test` ran it on the device. Reported only when the check asked for tests (run_tests).';
schemas.ValidationResult=object({id:{...id,description:'The validation.id of the manifest that asked, exactly as sent (lowercase, hyphenated).'},valid:{...bool,description:'The device validated the candidate with its own Vector, local capability policy and device-local secrets, and nothing it found is an error.'},diagnostics:{...nullable({...array(ref('AgentDiagnostic')),maxItems:20}),description:'At most 20 redacted findings, errors first, each at most 512 serialized bytes; the server keeps errors first whatever order they arrive in. Absent or null means none.'},tests:{...nullable({...array(ref('ValidationTest')),maxItems:100}),description:'At most 100. Absent or null means none.'},duration_ms:{...nullable(checkTime),description:'How long the device took. Absent or null means not reported.'},secrets_missing:{...nullable(secretNames),description:'Names only, sorted, at most 64: the device-secret names the candidate references that this device has not bound. Never file paths or values. Absent or null means none.'}},['id','valid'],false);
schemas.ValidationResult.description='The answer of one device to one check, sent in every heartbeat until the manifest it receives no longer carries that validation.id. Strict like every heartbeat member: unknown keys, an oversized list or text, a malformed ID, an answer that serializes to more than 128 KiB as the server stores it, refuse the whole heartbeat with 400 INVALID_INPUT (so an agent must not resend an answer the server refused). An answer for an ID that is unknown, belongs to another device, was already answered or has expired is ignored, never an error. It changes no desired state, generation, policy or issue.';
schemas.Readiness=schemas.Device.properties.readiness;
schemas.ManifestValidation=object({id:{...id,description:'The check this device answers. Every device of one request shares it; with the device it identifies the row.'},sha256:{...hash,description:'Digest of the candidate this device is asked to validate: the artifact the review computed for it, with its own variable values applied and device secrets still vectory-secret:NAME references.'},size:{type:'integer',minimum:1,maximum:16777216},artifact_path:{type:'string',pattern:'^/agent/v1/artifacts/[a-f0-9]{64}$',description:'Always the path of sha256. Only this device can fetch it, and only while the check is pending and unexpired.'},run_tests:{...bool,description:'Also run the pipeline\'s own tests (vector test).'},expires_at:{...date,description:'UTC, ten minutes after the check was requested.'}},undefined,false);
schemas.HeartbeatRequest.properties.agent_features={...nullable({type:'array',maxItems:16,items:{type:'string',pattern:'^[a-z_]{1,32}$'}}),description:'What this agent can do: validation means it can be checked on. Sent only after a verified manifest lists validation. The server keeps the latest announcement per device; a check-in without it means nothing is announced now. Null is treated as absent.'};
