schemas.HeartbeatRequest.properties.readiness={...nullable(object({data_dir_writable:nullable(bool),allowed_listener_count:nullable({type:'integer',minimum:0,maximum:1000000})},[],false)),description:'Booleans and counts only (data_dir_writable, allowed_listener_count), sent only after a verified manifest lists validation. configuration_mode and vector_version already ride every heartbeat. Null is treated as absent, here and for each member.'};
schemas.PreviewRequest={...schemas.DeploymentRequest,properties:{...schemas.DeploymentRequest.properties,device_validation:{type:'boolean',default:false,description:'Also ask every reviewed device that is not revoked, the first 50 by name, to validate this version on its own host. Needs a pipeline version (not agent settings). Creating a deployment refuses this field.'},run_tests:{type:'boolean',default:false,description:'With device_validation: also run the pipeline\'s own tests on each device. Stored with the check; it does nothing on its own.'}}};
