schemas.Preview.properties.validation_truncated={...bool,description:'Present with validation_id: true when more devices were reviewed than were addressed (the first 50 by name, and at most 10 MiB of candidate bytes in all).'};
schemas.DeviceValidationDevice=object({id,name:{...str,description:'The device\'s name when the check was requested.'},state:{enum:['pending','passed','failed','offline','expired','unsupported'],description:'pending: asked, not answered yet. passed: the device validated the candidate and found no error. failed: it found at least one (diagnostics, tests or secrets_missing say what). offline: it had not checked in for three of its own intervals (or never) when the check was requested, so it was not asked. expired: it did not answer in ten minutes, or a newer check for it replaced this one, or it was revoked. unsupported: it was online but had not announced validation in agent_features, so it was not asked (an older agent).'},valid:{...bool,description:'Present with passed and failed.'},diagnostics:{...array(ref('AgentDiagnostic')),maxItems:20},tests:{...array(ref('ValidationTest')),maxItems:100},secrets_missing:{...secretNames},duration_ms:checkTime,updated_at:{...date,description:'When this device last changed state: the request, the answer, the supersede or revocation, or the expiry.'}},['id','name','state','diagnostics','tests','secrets_missing','updated_at'],false);
schemas.DeviceValidation=object({id,state:{enum:['running','complete'],description:'running while any device is pending; complete otherwise (also once every pending device has expired).'},created_at:date,expires_at:date,truncated:{...bool,description:'More devices were reviewed than were addressed.'},run_tests:bool,devices:{type:'array',maxItems:50,items:ref('DeviceValidationDevice'),description:'In name order (digits compare by value: edge-2 before edge-10).'}},undefined,false);
schemas.DeviceValidation.description='What the devices of one preview answered when asked to validate a candidate version on their own hosts. Advisory: no deployment, desired state, generation, policy or issue changes because of an answer, and nothing waits for one. Diagnostics are redacted on the device; the server stores what it received within its bounds and keeps rows 24 hours.';
route('/api/v1/device-validations/{id}','get','The answers of the devices of one check on devices (Check on devices), for the operator who requested it or an administrator; anyone else, and an unknown or expired-and-pruned ID, gets 404. Operators and administrators; 429 beyond 240 reads a minute per account; no query parameters',ref('DeviceValidation'));
