schemas.OverviewCounts=object({total:{...integer,description:'Non-revoked devices.'},health:object(Object.fromEntries(healthBuckets.map(bucket=>[bucket,integer])),undefined,false),connection:{...object({online:integer,offline:integer,never:integer},undefined,false),description:'never: enrolled but never checked in.'},checked_in:integer,waiting_device:{...nullable(object({id,name:str},undefined,false)),description:'The first device by name that never checked in.'},telemetry:{...object({eligible:integer,reporting:integer,stale:integer,disabled:integer,events_in_per_second:metric,events_in_devices:integer,events_out_per_second:metric,events_out_devices:integer,errors:metric,errors_per_minute:metric,newest_sample_at:nullable(date)},undefined,false),description:'From each non-revoked device\'s latest sample when it is at most 3 minutes old (reporting); stale samples are older. A total no fresh device reported is null, never zero. errors sums counters since each Vector started. disabled counts devices without a fresh sample whose settings turn metrics off.'}},undefined,false);
