const utcInstant={type:'string',pattern:'^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}Z$',description:'A UTC instant in whole seconds: YYYY-MM-DDTHH:MM:SSZ, years 1970 to 9999.'};
const utcMilliseconds={type:'string',pattern:'^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}\\.[0-9]{3}Z$',description:'A UTC instant with milliseconds: YYYY-MM-DDTHH:MM:SS.mmmZ.'};
