const keyLine={type:'string',pattern:String.raw`^vectory-release-key ed25519 [A-Za-z0-9+/]{43}= [\x21\x23-\x5b\x5d-\x7e]([\x20\x21\x23-\x5b\x5d-\x7e]{0,62}[\x21\x23-\x5b\x5d-\x7e])?$`,description:'vectory-release-key ed25519 <base64 of the 32 raw bytes> <name>: single spaces, a name of 1 to 64 printable ASCII characters that neither start nor end with a space and hold no quotation mark and no backslash. The 32 bytes must also be the canonical encoding of a curve point that is not of small order, which a pattern cannot say: RELEASE_KEY_INVALID.'};
const agentUpdateCodes=[...AGENT_UPDATE_CODES];
const eligibilityCodes=[...AGENT_UPDATE_ELIGIBILITY];
