schemas.AgentUpdateLast.description='The privileged step\'s latest result for a request that ended. code is null exactly when outcome is committed.';

// What the agent sends and what the server offers.
const updateWindows={type:'array',maxItems:7,items:{type:'string',minLength:1,maxLength:40,pattern:'^[\\x20-\\x7e]+$'},description:'Update windows as written in the policy: DAYS HH:MM-HH:MM, optionally followed by UTC. Empty means any time.'};
const updateKeys={type:'array',maxItems:4,uniqueItems:true,items:fingerprint};
schemas.AgentUpdateReport=object({consent:{enum:['off','auto','ask']},paused:bool,track:{enum:['patch','minor']},windows:updateWindows,window_open:{...bool,description:'True when the host has no window or one is open now.'},next_window_at:{...nullable(utcInstant),description:'The start of the next window; absent or null while one is open or there is none.'},keys:{...updateKeys,description:'The keys the host pins now.'},highest_counter:{type:'integer',minimum:0,maximum:maxSafe,description:'The highest release counter the host attempted from any key it pins; 0 when none.'},eligibility:{enum:eligibilityCodes},service_definition:{...nullable({type:'integer',minimum:1,maximum:1000}),description:'The generation of the service definition the host has; absent while the privileged step is not installed.'},state:{enum:AGENT_UPDATE_STATES},release:{...nullable(hash),description:'The manifest SHA-256 that state is about; present from downloading to trial.'},code:{...nullable({enum:agentUpdateCodes}),description:'Present in refused and failed; also UPDATES_OFF and UPDATES_PAUSED.'},rollover_conflict:{...nullable(ref('RolloverConflict')),description:'Present exactly when code is KEY_ROLLOVER_CONFLICT.'},last:{...nullable(ref('AgentUpdateLast')),description:'The privileged step\'s latest result, copied from its status file.'}},['consent','paused','track','windows','window_open','keys','highest_counter','eligibility','state'],false);
schemas.AgentUpdateReport.description='The heartbeat member agent_update, sent only after a verified manifest lists the feature. Allowlisted: an unknown member, a bound broken or a relation broken (a state about a release names it, refused and failed have a code, a host that is off is idle, rollover_conflict and its code go together) makes the heartbeat a 400 that changes nothing. contracts/fixtures/agent-release/report.json holds the bounds and members both sides test against.';
schemas.AgentUpdateOffer=object({rollout_id:id,release_id:id,manifest:{type:'string',maxLength:21848,pattern:'^[A-Za-z0-9+/]+={0,2}$',description:'Base64 of the exact bytes of release.json.'},signatures:{type:'string',maxLength:5464,pattern:'^[A-Za-z0-9+/]+={0,2}$',description:'Base64 of the exact bytes of release.json.sig.'},rollovers:{type:'array',maxItems:8,items:ref('KeyRolloverEnvelope'),description:'The statements that lead from a key the device reported pinning to the release\'s signer, in the order a host follows them.'},artifact:object({sha256:hash,size:{type:'integer',minimum:1,maximum:agentBuildLimit},path:{type:'string',pattern:'^/agent/v1/agent-releases/[a-f0-9]{64}$'}},undefined,false)},undefined,false);
schemas.AgentUpdateOffer.description='Manifest member agent_update: an offer for a device in a stage of an active update rollout, inside the signed manifest. It authorizes no code: the agent derives everything from manifest after verifying signatures and rollovers against its own pins, and requires artifact to be the manifest\'s entry for its platform and path to end in that digest.';
schemas.HeartbeatRequest.properties.agent_update={...nullable(ref('AgentUpdateReport')),description:'Agent updates: the host\'s consent, pins, counters, eligibility and the state of an offer. Sent only after a verified manifest lists the agent_update feature. The agent leaves it out first when a heartbeat is refused as invalid, and for the rest of the process.'};
schemas.Manifest.properties.agent_update={...ref('AgentUpdateOffer'),description:'At most one, optional: the offer of an agent build to this device. Present only while updates are on and not stopped, for a device in a stage of an active update rollout. Covered by the signature and bound to the recipient and nonce like every other member. Older agents ignore it.'};
schemas.Manifest.properties.features.description=schemas.Manifest.properties.features.description.replace('and wake while it holds','agent_update (the agent_update heartbeat member and offer, listed only while agent updates are on), and wake while it holds');

// The host's files. Strict JSON, every member always written, at most 4 KiB unless said.
const stageNames=['preparing','swapping','trial','rolling_back'];
const counterFloors={type:'object',maxProperties:4,propertyNames:{pattern:'^[a-f0-9]{64}$'},additionalProperties:{type:'integer',minimum:0,maximum:maxSafe},description:'Fingerprint to the highest counter attempted from that key.'};
const storedCounterFloors={...counterFloors,maxProperties:16,description:'Fingerprint to the highest counter attempted from that key, for every key the host pins and for the keys it pinned before.'};
const bootId={...hash,description:'A process\'s boot_id: 64 lowercase hex.'};
const fileName={type:'string',minLength:1,maxLength:255,pattern:'^[^/\\\\\\x00]+$'};
schemas.UpdateRollovers=object({schema:{const:'vectory.update-rollovers.v1'},rollovers:{type:'array',maxItems:8,items:ref('KeyRolloverEnvelope')}},undefined,false);
schemas.UpdateRollovers.description='<state>/updates/incoming/<manifest sha256>/rollovers.json, written by the agent for the privileged step: the offer\'s rollover envelopes. At most 16 KiB.';
schemas.UpdatePolicy=object({schema:{const:'vectory.update-policy.v1'},consent:{enum:['off','auto','ask']},track:{enum:['patch','minor']},windows:updateWindows,paused:bool,keys:{type:'array',maxItems:4,items:object({public_key:keyLine,pinned_at:utcInstant},undefined,false)},updated_at:utcInstant},undefined,false);
schemas.UpdatePolicy.description='The host\'s consent, written only by root outside the agent\'s state directory (policy.json). A missing file means off. At least one key when consent is auto or ask; a window is DAYS HH:MM-HH:MM with an optional UTC, at most 40 characters.';
schemas.UpdateRequest=object({schema:{const:'vectory.update-request.v1'},manifest_sha256:hash,artifact_sha256:hash,rollout_id:id,offered_at:utcInstant},undefined,false);
schemas.UpdateRequest.description='<state>/updates/request.json, written by the agent last. rollout_id and offered_at are for people and logs; the privileged step verifies the manifest, the pins and the policy itself and never reads consent from here.';
schemas.UpdateHealth=object({schema:{const:'vectory.update-health.v1'},agent_sha256:hash,agent_version:identifying(128),boot_id:bootId,checked_in_at:utcMilliseconds,vector:{enum:['running','stopped','none']},offer:{...nullable(hash),description:'The manifest SHA-256 the verified manifest of that check-in offered, or null.'}},undefined,false);
schemas.UpdateHealth.description='<state>/updates/health.json, written by the agent after every successful check-in. Advice for people and for the trial\'s health test, never evidence of freshness.';
schemas.UpdateCounters=object({schema:{const:'vectory.update-counters.v1'},highest_counters:storedCounterFloors,rollover_conflict:nullable(ref('RolloverConflict'))},undefined,false);
schemas.UpdateCounters.description='private/counters.json: the counter floors the privileged step keeps, raised and synced just before it journals swapping and never lowered, moved or removed (at most 16 keys, the lowest going first), and the fork it found, cleared only by re-pinning.';
schemas.UpdateInstalled=object({schema:{const:'vectory.update-installed.v1'},version:identifying(128),sha256:hash,release:nullable(hash),recorded_at:utcInstant},undefined,false);
schemas.UpdateInstalled.description='private/installed.json: the installed build, rewritten at commit. release is the manifest SHA-256 it came from, null for the build setup installed.';
schemas.UpdateStatus=object({schema:{const:'vectory.update-status.v1'},run_at:utcInstant,stage:{enum:['idle',...stageNames]},eligibility:{enum:eligibilityCodes},service_definition:{type:'integer',minimum:1,maximum:1000},highest_counters:counterFloors,rollover_conflict:nullable(ref('RolloverConflict')),release:nullable(hash),from_version:nullable(identifying(128)),to_version:nullable(releaseVersion),deadline:nullable(utcInstant),last:nullable(ref('AgentUpdateLast'))},undefined,false);
schemas.UpdateStatus.description='status.json in the privileged step\'s directory, written at every run and world-readable, so the agent can tell the step is alive. highest_counters means attempted. release, from_version, to_version and deadline describe the request in progress and are null while idle.';
schemas.UpdateJournal=object({schema:{const:'vectory.update-journal.v1'},stage:{enum:[...stageNames,'committed','rolled_back']},release:hash,signers:{type:'array',maxItems:4,uniqueItems:true,items:fingerprint},counter:nullable({type:'integer',minimum:1,maximum:maxSafe}),from:nullable(object({version:identifying(128),sha256:hash},undefined,false)),to:nullable(object({version:releaseVersion,sha256:hash},undefined,false)),started_at:utcInstant,deadline:nullable(utcInstant),boot_id_before:nullable(bootId),interruptions:{type:'integer',minimum:0,maximum:1},swap:nullable(object({style:{enum:['rename','two_renames']},staged:fileName,previous:fileName},undefined,false)),code:nullable({enum:agentUpdateCodes}),finished_at:nullable(utcInstant)},undefined,false);
schemas.UpdateJournal.description='private/journal.json, written and synced before each step it names. No file, or committed or rolled_back, is idle. The stage names and the members are the contract; the formats are fixed within a service_definition generation.';

// The dashboard API.
schemas.AgentReleaseKey=object({fingerprint,public_key:keyLine,custody:custodyKind,state:{enum:['current','retired','revoked']},created_at:date,created_by_name:nullable(bounded(120)),retired_at:nullable(date),revoked_at:nullable(date),revoked_reason:nullable(bounded(500)),introduced_by:nullable(ref('KeyRolloverEnvelope')),devices_pinning:{...integer,description:'Non-revoked devices whose latest report lists this fingerprint.'},device_names:{type:'array',maxItems:20,items:bounded(240)}},undefined,false);
schemas.AgentReleaseKey.description='A release key. There is one current key at a time. Custody is published only here; the unauthenticated key bundle has none.';
schemas.AgentUpdateFleet=object({devices_total:integer,versions:{type:'array',maxItems:50,items:object({version:bounded(128),devices:integer},undefined,false),description:'Agent versions the fleet reports, newest first; versions that are not valid versions count under "unknown", last.'},levels:object({automatic:integer,ask:integer,off:integer,cannot_update:integer,not_reported:integer},undefined,false)},undefined,false);
schemas.AgentUpdateFleet.description='Real counts from the devices\' reports, over non-revoked devices. Each device is in one bucket, tested in the order not_reported, cannot_update, then off, ask or automatic, so the five add up to devices_total.';
schemas.AgentUpdateCatalogEntry=object({version:releaseVersion,platforms:array(object({os:platformOs,arch:platformArch},undefined,false)),devices_behind:integer,release:nullable(object({id,state:releaseState},undefined,false))},undefined,false);
schemas.AgentUpdates=object({enabled:bool,custody:{...nullable(custodyKind),description:'Chosen once, when updates are turned on; null until a key exists. Stays when updates are turned off.'},revision:auditInteger,current_key:nullable(ref('AgentReleaseKey')),stopped:nullable(object({reason:updateReason,by_name:nullable(bounded(120)),at:date},undefined,false)),active_rollouts:integer,fleet:{...nullable(ref('AgentUpdateFleet')),description:'Null while updates are off.'},frozen_devices:{...nullable(object({total:integer,items:{type:'array',maxItems:20,items:object({device_id:id,device_name:nullable(bounded(240)),rollover_conflict:ref('RolloverConflict')},undefined,false)}},undefined,false)),description:'Hosts frozen on a fork of the rollover chain until they are re-pinned: the non-revoked devices whose latest report carries a rollover_conflict, at most 20 by name. Null while updates are off.'},catalog:{...nullable({type:'array',maxItems:20,items:ref('AgentUpdateCatalogEntry')}),description:'Versions in this server\'s agent catalog newer than at least one device\'s agent, newest first. Null while updates are off.'}},undefined,false);
schemas.AgentUpdates.description='The agent update setting. It answers while updates are off; every other agent update route answers 404 AGENT_UPDATES_OFF then.';
schemas.AgentRelease=object({id,version:releaseVersion,counter:{type:'integer',minimum:1,maximum:maxSafe},state:releaseState,expired:{...bool,description:'expires_at is not in the future: such a release is not offered and cannot start a rollout.'},manifest_sha256:{...hash,description:'The SHA-256 of the stored manifest bytes: the digest a host reports as release.'},issued_at:date,expires_at:date,signer:nullable(object({fingerprint,custody:custodyKind},undefined,false)),artifacts:{type:'array',minItems:1,maxItems:8,items:object({os:platformOs,arch:platformArch,file:bounded(128),size:{type:'integer',minimum:1,maximum:agentBuildLimit},sha256:hash},undefined,false)},prepared_by_name:nullable(bounded(120)),prepared_at:date,withdrawn_at:nullable(date),withdrawn_reason:nullable(bounded(500)),rollouts:{type:'array',maxItems:50,items:object({id,status:rolloutStatus},undefined,false)}},undefined,false);
schemas.AgentRelease.description='A build this server ships, prepared as a release with a counter and a manifest. awaiting_signature releases wait for a signature the team\'s offline key makes.';
schemas.AgentUpdateRolloutSettings=object({canary_size:{type:'integer',minimum:1,maximum:100,default:1},batch_size:{type:'integer',minimum:1,maximum:50,default:10},observation_seconds:{type:'integer',minimum:60,maximum:86400,default:300},failure_threshold:{type:'integer',minimum:0,maximum:100,default:0,description:'A count of devices.'},canary_device_ids:{type:'array',maxItems:100,uniqueItems:true,items:id,description:'Distinct lowercase device UUIDs, at most canary_size, each a device the request targets (otherwise 400 INVALID_INPUT). Fewer than canary_size lets the most ready of the other targets fill the canary.'}},['canary_size','batch_size','observation_seconds','failure_threshold'],false);
const rolloutRequestSettings={...schemas.AgentUpdateRolloutSettings,required:[],description:'Members left out take their defaults (canary_size 1, batch_size 10, observation_seconds 300, failure_threshold 0). There is no all-at-once form: an update rollout always has a canary.'};
schemas.AgentUpdateRollout=object({id,name:nullable(bounded(120)),release:object({id,version:releaseVersion,counter:{type:'integer',minimum:1,maximum:maxSafe},manifest_sha256:hash},undefined,false),selector:ref('Selector'),rollout:ref('AgentUpdateRolloutSettings'),status:rolloutStatus,failure_reason:nullable({enum:['threshold','data_plane']}),cancel_reason:nullable({enum:['operator','stop','key_revoked','release_withdrawn']}),revision:auditInteger,created_at:date,created_by_name:nullable(bounded(120)),paused_at:nullable(date),completed_at:nullable(date),failed_at:nullable(date),cancelled_at:nullable(date),observation_started_at:nullable(date),target_count:integer,state_counts:object(Object.fromEntries(targetStates.map(state=>[state,integer])),undefined,false),degraded:{...integer,description:'verified targets on which a data-plane issue (DATA_PLANE_*) is open; they count as failures during an observation.'},request_id:{...id,description:'The normalized request_id of a keyed creation response.'}},['id','name','release','selector','rollout','status','failure_reason','cancel_reason','revision','created_at','created_by_name','paused_at','completed_at','failed_at','cancelled_at','observation_started_at','target_count','state_counts','degraded'],false);
schemas.AgentUpdateRollout.description='An update rollout: its own object, never a deployment. It targets the devices its review resolved, starts with a canary, and counts a device as updated only from verified.';
schemas.AgentUpdateStage=object({kind:{enum:['canary','batch']},index:integer,state:{enum:['queued','in_progress','observing','passed','failed','stopped']},released_at:nullable(date),size:integer,counts:{type:'object',additionalProperties:integer},devices:{type:'array',maxItems:60,items:object({device_id:id,device_name:nullable(bounded(240)),state:{enum:targetStates},code:nullable(bounded(64))},undefined,false)},more:integer},undefined,false);
schemas.AgentUpdateFailure=object({state:{enum:['rolled_back','failed','refused']},code:nullable(bounded(64)),message:nullable(bounded(500)),count:integer,device_ids:{type:'array',maxItems:1000,items:id},devices:{type:'array',maxItems:8,items:object({device_id:id,device_name:nullable(bounded(240))},undefined,false)}},undefined,false);
schemas.AgentUpdateRolloutDetail=object({...schemas.AgentUpdateRollout.properties,stages:array(ref('AgentUpdateStage')),failures:array(ref('AgentUpdateFailure')),evaluated_at:date,check_in_seconds:nullable({type:'integer',minimum:10,maximum:3600})},[...schemas.AgentUpdateRollout.required,'stages','failures','evaluated_at','check_in_seconds'],false);
schemas.AgentUpdateRolloutPage=object({items:{type:'array',maxItems:50,items:ref('AgentUpdateRollout')},total:integer,page:pageNumber,page_size:{type:'integer',minimum:1,maximum:50}},undefined,false);
schemas.AgentUpdateTarget=object({device_id:id,device_name:nullable(bounded(240)),stage:nullable(integer),state:{enum:targetStates},code:nullable(bounded(64)),from_version:nullable(bounded(128)),to_version:releaseVersion,released_at:nullable(date),updated_at:date,verified_at:nullable(date)},undefined,false);
schemas.AgentUpdateTargetPage=object({items:{type:'array',maxItems:50,items:ref('AgentUpdateTarget')},total:integer,page:pageNumber,page_size:{type:'integer',minimum:1,maximum:50}},undefined,false);
const reviewDevice=object({device_id:id,device_name:nullable(bounded(240))},undefined,false);
schemas.AgentUpdatePreview=object({release:object({id,version:releaseVersion,counter:{type:'integer',minimum:1,maximum:maxSafe},manifest_sha256:hash},undefined,false),will_update:{type:'array',maxItems:10000,items:object({device_id:id,device_name:nullable(bounded(240)),consent:{enum:['auto','ask']},windows:updateWindows,next_window_at:nullable(date)},undefined,false)},wont_update:{type:'array',maxItems:64,items:object({code:{enum:reviewCodes},reason:bounded(500),fix:{...nullable(bounded(500)),description:'A sentence for people, null when nothing on the host would change it; the dashboard turns it into the host command it generates.'},devices:{type:'array',maxItems:10000,items:object({device_id:id,device_name:nullable(bounded(240)),successors:{...nullable({type:'array',minItems:2,maxItems:2,items:fingerprint}),description:'KEY_ROLLOVER_CONFLICT only: the two successors of the fork.'}},undefined,false)}},undefined,false)},warnings:{type:'array',maxItems:8,items:object({code:{enum:['OFFLINE','WAITS_FOR_HOST','WAITS_FOR_WINDOW','PAUSED_ON_HOST']},message:bounded(500),devices:{type:'array',maxItems:10000,items:reviewDevice}},undefined,false)},canary:object({size:integer,chosen_by_you:bool,device_ids:{type:'array',maxItems:100,items:id}},undefined,false),review_token:hash},undefined,false);
schemas.AgentUpdatePreview.description='The review of an update rollout, read-only. Every device of the resolved selector is in will_update or under the first reason that applies, in the order the contract lists them. The token binds the release, the rollout settings, the exact sets and the canary.';
schemas.DeviceAgentUpdate=object({consent:{enum:['off','auto','ask']},paused:bool,track:{enum:['patch','minor']},windows:updateWindows,window_open:bool,next_window_at:nullable(utcInstant),keys:updateKeys,eligibility:{enum:eligibilityCodes},state:{enum:AGENT_UPDATE_STATES},release_version:{...nullable(releaseVersion),description:'The version of the release the report\'s release digest names, null when it names none this server prepared.'},code:nullable({enum:agentUpdateCodes}),rollover_conflict:nullable(ref('RolloverConflict')),last:nullable(ref('AgentUpdateLast')),reported_at:date},undefined,false);
schemas.DeviceAgentUpdate.description='What the device last reported about agent updates, as it sent it: never inferred, and absent when the device sent nothing (the dashboard says Not reported). A download or a staged build is not an update.';
schemas.Device.properties.agent_update={...ref('DeviceAgentUpdate'),description:'Only while agent updates are on and the device reported it. List rows do not carry it.'};
const attentionCause=schemas.AttentionGroup.properties.cause;
attentionCause.enum.push('agent_update');
attentionCause.description+=' agent_update: devices with an open AGENT_UPDATE_ROLLED_BACK or AGENT_UPDATE_FAILED issue (severity warning; state rolled_back or failed; reason the most common code), only while agent updates are on.';
schemas.NotificationEvent.properties.agent_update={...nullable(object({release_version:nullable(releaseVersion),rollout:nullable(object({id,name:bounded(120)},undefined,false)),code:nullable(bounded(64)),key:{...nullable({type:'string',pattern:'^[a-f0-9]{16}$'}),description:'The short ID of the key that became current (agent_update.key_changed).'}},undefined,false)),description:'agent_update.* events only: the release, rollout, agent code and key the event is about.'};

const requestBodies={
  settings:object({enabled:bool,custody:object({kind:custodyKind,public_key:keyLine},['kind'],false),current_password:str,revision:auditInteger},['enabled','current_password','revision'],false),
  stop:object({reason:updateReason},undefined,false),
  clear:object({revision:auditInteger},undefined,false),
  password:object({current_password:str},undefined,false),
  rollover:object({statement:schemas.KeyRolloverEnvelope.properties.statement,signature:base64Signature,current_password:str},undefined,false),
  revoke:object({reason:updateReason,current_password:str},undefined,false),
  prepare:object({version:releaseVersion},undefined,false),
  withdraw:object({reason:updateReason},undefined,false),
  preview:object({release_id:id,selector:ref('Selector'),rollout:rolloutRequestSettings},undefined,false),
  create:object({release_id:id,selector:ref('Selector'),rollout:rolloutRequestSettings,name:{...bounded(120),description:`Optional; at most 120 characters. ${oneLine}`},review_token:hash,request_id:id},['release_id','selector','rollout','review_token'],false),
};
const addResponses=(path,method,codes)=>{for(const [status,description] of Object.entries(codes))paths[path][method].responses[status]={description,content:{'application/json':{schema:ref('Error')}}};};
const offNote='404 AGENT_UPDATES_OFF while updates are off.';
route('/api/v1/agent-updates','get','Agent updates: whether they are on, the custody, the current release key, the stop state, the fleet\'s agent versions and update levels from the devices\' reports, and the builds in this server\'s catalog newer than the fleet. Any signed-in role; answers while updates are off',ref('AgentUpdates'));
route('/api/v1/agent-updates/settings','put','Administrator, password and CSRF: turn agent updates on or off. Turning on chooses the custody once (the server generates and seals a key, or the team supplies the public half of a key it keeps offline) and the custody is fixed while updates are on (409 CUSTODY_LOCKED); 409 CUSTODY_REQUIRED without a custody when there is no current key; 409 AGENT_UPDATE_ROLLOUTS_ACTIVE turning off while an update rollout is active or paused; 422 RELEASE_KEY_INVALID, 409 RELEASE_KEY_IN_USE; 409 STALE_REVISION. Audited as agent_update.enable and agent_update.disable',ref('AgentUpdates'),requestBodies.settings);
addResponses('/api/v1/agent-updates/settings','put',{'422':'RELEASE_KEY_INVALID: not a valid public key line'});
route('/api/v1/agent-updates/stop','post',`Operator or Administrator, CSRF: Stop all updates. In one transaction it cancels every active or paused update rollout, withdraws every offer, makes the download route refuse, answers the waiting agents and refuses new rollouts until an Administrator clears it. A device that already downloaded a build may still start applying it until its next check-in reaches it. Audited as agent_update.stop. ${offNote}`,ref('AgentUpdates'),requestBodies.stop);
route('/api/v1/agent-updates/stop/clear','post',`Administrator, CSRF: clear Stop all updates. It resumes nothing. 409 STALE_REVISION, 409 CONFLICT when nothing is stopped. Audited as agent_update.stop_clear. ${offNote}`,ref('AgentUpdates'),requestBodies.clear);
route('/api/v1/agent-release-keys','get',`Release keys, newest first, at most 64, with their custody, state and the devices that pin each. Any signed-in role. ${offNote}`,array(ref('AgentReleaseKey')));
route('/api/v1/agent-release-keys/rotate','post',`Administrator, password and CSRF: rotate the server's own key (server custody only, 409 CONFLICT otherwise). The server generates the successor, signs a rollover statement with the current key and makes the successor current. Audited as agent_release_key.rotate. ${offNote}`,ref('AgentReleaseKey'),requestBodies.password);
route('/api/v1/agent-release-keys/rollover','post',`Administrator, password and CSRF: upload the rollover statement the current offline key signed for its successor (offline custody only, 409 CONFLICT otherwise; custody never changes by a statement). 422 RELEASE_KEY_INVALID, 422 RELEASE_SIGNATURE_INVALID, 409 RELEASE_KEY_IN_USE. Audited as agent_release_key.rollover. ${offNote}`,ref('AgentReleaseKey'),requestBodies.rollover);
addResponses('/api/v1/agent-release-keys/rollover','post',{'422':'RELEASE_KEY_INVALID or RELEASE_SIGNATURE_INVALID'});
route('/api/v1/agent-release-keys/{fingerprint}/revoke','post',`Administrator, password and CSRF: revoke a key. It withdraws the releases only it signed, ends the rollouts that offer them and removes the key and its statements from the key bundle. 404 NOT_FOUND, 409 CONFLICT when already revoked. Audited as agent_release_key.revoke. ${offNote}`,ref('AgentReleaseKey'),requestBodies.revoke);
route('/api/v1/agent-releases','get',`Releases, newest first, at most 100. Any signed-in role. ${offNote}`,array(ref('AgentRelease')));
route('/api/v1/agent-releases','post',`Administrator, CSRF: prepare the release of a version in this server's agent catalog. It copies each platform's build, re-hashed, into the release store, assigns the next counter, builds the manifest and, with server custody, signs it at once; with offline custody it waits for a signature. 409 RELEASE_NOT_IN_CATALOG, RELEASE_EXISTS, CUSTODY_REQUIRED; 507 RELEASE_STORAGE_FULL. Audited as agent_release.prepare and agent_release.sign. ${offNote}`,ref('AgentRelease'),requestBodies.prepare);
addResponses('/api/v1/agent-releases','post',{'507':'RELEASE_STORAGE_FULL: twenty releases that are not withdrawn, or the release store is full'});
route('/api/v1/agent-releases/{id}','get',`One release. Any signed-in role. ${offNote}`,ref('AgentRelease'));
route('/api/v1/agent-releases/{id}/manifest','get',`The exact stored bytes of release.json, in any state, for an offline signer to sign (Content-Disposition attachment, ETag the manifest SHA-256). Any signed-in role. ${offNote}`,{type:'string'});
route('/api/v1/agent-releases/{id}/signature','put',`Administrator, CSRF: the raw bytes of a release.json.sig (at most 4 KiB) for a release awaiting its signature. It must be a valid signature file with an entry for the current key that verifies over the release prefix and the stored manifest, else 422 RELEASE_SIGNATURE_INVALID, audited as refused. Audited as agent_release.signature_upload. ${offNote}`,ref('AgentRelease'));
route('/api/v1/agent-releases/{id}/withdraw','post',`Administrator, CSRF: withdraw a release and cancel its active or paused rollouts. 409 CONFLICT when already withdrawn. Audited as agent_release.withdraw. ${offNote}`,ref('AgentRelease'),requestBodies.withdraw);
route('/api/v1/agent-update-rollouts','get',`Update rollouts, newest first. Any signed-in role. ${offNote}`,ref('AgentUpdateRolloutPage'));
route('/api/v1/agent-update-rollouts','post',`Operator or Administrator, CSRF: start an update rollout from a review. The review token is rechecked in the writer transaction (409 UPDATE_REVIEW_CHANGED). 409 AGENT_UPDATES_STOPPED, RELEASE_NOT_READY, NOTHING_TO_UPDATE, UPDATE_ROLLOUT_OVERLAP, IDEMPOTENCY_CONFLICT. An optional request_id makes an identical retry return the original rollout. Audited as agent_update_rollout.create. ${offNote}`,ref('AgentUpdateRollout'),requestBodies.create);
route('/api/v1/agent-update-rollouts/preview','post',`Operator or Administrator, CSRF: review an update rollout. It resolves the selector and lists the devices that will update and, under the reason that applies, those that will not, with warnings and a review token. Writes nothing. 409 RELEASE_NOT_READY. ${offNote}`,ref('AgentUpdatePreview'),requestBodies.preview);
